        ['من أي شيء يشرب رواد الفضاء؟','من كيس بماصة',['من كوب مفتوح','من زجاجة مفتوحة','من أيديهم'],'الشرب المكشوف سيطير في الهواء.','يشربون من كيس لين بماصة وإلا طار الشراب.','القطرة المسكوبة تصير كرة سابحة.',1],
        ['ماذا ترى تحتك من محطة الفضاء؟','الأرض',['الشمس','المريخ','لا شيء إطلاقًا'],'أنت تطير فوقها مباشرة.','المحطة تدور حول الأرض، فالأرض دائمًا تحتك.','من النافذة المستديرة تمر بلدان كاملة.',1],
        ['من أين يخرج رائد الفضاء؟','من حجرة معادلة الضغط',['من النافذة','من الباب الأمامي','من فتحة في الأرضية'],'يُغلق باب قبل أن يُفتح الآخر.','تُفرغ الحجرة من الهواء قبل الخروج إلى الفضاء.','بدونها سيخرج كل الهواء دفعة واحدة.',1],
        ['ماذا يلبس رائد الفضاء على رأسه؟','خوذة',['قبعة','طاقية صوف','قبعة شمسية'],'تُثبَّت في البدلة.','الخوذة تحفظ الهواء بالداخل وتمنع ضوء الشمس الحاد.','وفيها أيضًا ميكروفون للحديث.',1],
        ['كيف يغسل رواد الفضاء شعرهم؟','بشامبو بلا ماء',['تحت الدش','في حوض استحمام','لا يغسلونه أبدًا'],'الماء سيطير في كل مكان.','يستعملون شامبو خاصًا لا يحتاج إلى شطف.','لا يوجد في المحطة دش يسقط منه الماء.',2],
        ['من أين يأتي الهواء في محطة الفضاء؟','من الماء بالكهرباء',['من الفضاء مباشرة','من نباتات على متنها','من أسطوانات من الأرض'],'الكهرباء تفصل سائلًا معروفًا.','آلة تفصل الماء بالكهرباء إلى أكسجين وهيدروجين.','الألواح الشمسية توفر تلك الكهرباء.',2],
        ['كم مرة في اليوم يرون هناك شروق الشمس؟','ست عشرة مرة',['مرة واحدة','مرتين','ولا مرة'],'يدورون حول الأرض في ساعة ونصف.','المحطة تدور بسرعة حتى تشرق الشمس ست عشرة مرة يوميًا.','الدورة الواحدة نحو تسعين دقيقة.',2],
        ['ماذا يحدث للدموع في انعدام الوزن؟','تلتصق بالعين',['تسقط إلى أسفل','تتبخر فورًا','تتجمد'],'لا شيء يسحبها إلى أسفل.','تبقى الدموع على العين ككرة صغيرة من الماء.','يمسحها الرواد بقطعة قماش.',2],
        ['لماذا بدلة الفضاء بيضاء؟','لتصد الحرارة',['لأنها جميلة','لتشبه الثلج','لتظهر الأوساخ'],'الأبيض يعكس ضوء الشمس.','الأبيض يعكس الشمس الحارقة فلا تسخن البدلة كثيرًا.','وفي الظل قد تصبح شديدة البرودة.',2],
        ['ماذا يحدث لنفايات محطة الفضاء؟','تذهب في سفينة شحن',['تُرمى في الفضاء','تُحرق على متنها','تبقى في خزانة'],'تعود معها إلى الغلاف الجوي.','توضع النفايات في سفينة شحن تحترق لاحقًا في الغلاف الجوي.','هكذا لا تبقى خردة تدور حول الأرض.',3],
        ['كم دامت أطول رحلة فضائية لشخص واحد؟','أكثر من سنة',['أسبوعًا','شهرًا','عشر سنوات'],'أكثر من أربعمئة يوم.','بقي فاليري بولياكوف 437 يومًا متواصلة في الفضاء.','هذا الرقم صامد منذ 1995.',3],
        ['كم دولة تعمل معًا في محطة الفضاء؟','خمس عشرة',['اثنتان','خمسون','مئة'],'أكثر من عشر وأقل من عشرين.','محطة الفضاء الدولية تعاون بين خمس عشرة دولة.','تشارك الدول الأوروبية عبر وكالتها الفضائية.',3],
        ['من وطئت قدمه القمر أولًا؟','نيل أرمسترونغ',['يوري غاغارين','باز ألدرين','مايكل كولينز'],'نزل السلم أولًا عام 1969.','خطا نيل أرمسترونغ أول خطوة على القمر في 20 يوليو 1969.','أثر قدمه ما زال هناك لأن لا رياح تهب.',3],
        ['لماذا يُحمل رائد الفضاء بعد الهبوط؟','ساقاه ما زالتا ضعيفتين',['هذا جزء من الاحتفال','ممنوع أن يلمس الأرض','بدلته ثقيلة جدًا'],'لم يقف على قدميه منذ شهور.','بعد شهور من الطفو تحتاج الساقان إلى التعود على الجاذبية.','بعد أسابيع من التمرين يعود كل شيء طبيعيًا.',3],
        ['من قام بأول سير في الفضاء؟','أليكسي ليونوف',['يوري غاغارين','نيل أرمسترونغ','أندريه كايبرس'],'حدث ذلك عام 1965 وهو مربوط بحبل.','عام 1965 خرج أليكسي ليونوف أول مرة خارج مركبته.','انتفخت بدلته حتى كاد لا يعود إلى الداخل.',4],
        ['كم تزن بدلة الفضاء على الأرض؟','نحو 120 كيلوغرامًا',['نحو 10 كيلوغرامات','نحو 50 كيلوغرامًا','نحو 300 كيلوغرام'],'أثقل من شخص بالغ.','تزن البدلة الكاملة على الأرض نحو 120 كيلوغرامًا.','أما في الفضاء فلا تشعر بثقلها.',4],
        ['لماذا يتنفس رائد الفضاء أكسجينًا نقيًا أولًا؟','للتخلص من النيتروجين',['ليشم بشكل أفضل','ليبقى مستيقظًا','ليملأ البدلة'],'وإلا تكونت فقاعات في دمه.','تنفس الأكسجين النقي يطرد النيتروجين من الدم.','يفعل الغواصون شيئًا مشابهًا عند الصعود.',4],
        ['على أي ارتفاع تطير محطة الفضاء؟','نحو 400 كيلومتر',['نحو 40 كيلومترًا','نحو 4000 كيلومتر','نحو 40000 كيلومتر'],'مسافة مدينة إلى أخرى، لكن إلى أعلى.','تطير المحطة الدولية على ارتفاع نحو 400 كيلومتر.','هناك يبقى قليل من الهواء يبطئها.',4],
        ['ما اسم محطة الفضاء الصينية؟','تيانغونغ',['مير','سكاي لاب','أرتميس'],'الاسم يعني قصر السماء.','تيانغونغ هي محطة الفضاء الخاصة بالصين.','تتكون من ثلاثة أجزاء على شكل حرف T.',4]
